#include <zstd.h>
#include <algorithm>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <span>
#include <stdexcept>
#include <string>
#include <vector>
struct Image{uint32_t w{},h{},bx{},by{};std::vector<uint8_t>raw;};
struct Band{uint32_t row{},rows{};std::vector<uint8_t>z;};
using Clock=std::chrono::steady_clock;
static uint32_t u24(const uint8_t*p){return uint32_t(p[0])|(uint32_t(p[1])<<8)|(uint32_t(p[2])<<16);}
static Image load(const char*p){std::ifstream f(p,std::ios::binary);std::vector<uint8_t>b((std::istreambuf_iterator<char>(f)),{});if(b.size()<16||b[0]!=0x13||b[1]!=0xab||b[2]!=0xa1||b[3]!=0x5c)throw std::runtime_error("bad ASTC");Image a;a.w=u24(b.data()+7);a.h=u24(b.data()+10);a.bx=(a.w+7)/8;a.by=(a.h+7)/8;a.raw.assign(b.begin()+16,b.end());if(a.raw.size()!=size_t(a.bx)*a.by*16)throw std::runtime_error("bad size");return a;}
static std::vector<uint8_t> compress(std::span<const uint8_t>x){std::vector<uint8_t>z(ZSTD_compressBound(x.size()));auto n=ZSTD_compress(z.data(),z.size(),x.data(),x.size(),3);if(ZSTD_isError(n))throw std::runtime_error(ZSTD_getErrorName(n));z.resize(n);return z;}
static std::vector<Band>make_bands(const Image&a,uint32_t pixels){uint32_t rows=(pixels+7)/8;std::vector<Band>b;for(uint32_t r=0;r<a.by;r+=rows){Band q{r,std::min(rows,a.by-r),{}};auto p=std::span<const uint8_t>(a.raw).subspan(size_t(r)*a.bx*16,size_t(q.rows)*a.bx*16);q.z=compress(p);b.push_back(std::move(q));}return b;}
static bool whole(ZSTD_DCtx*ctx,const std::vector<uint8_t>&z,std::span<uint8_t>out){auto n=ZSTD_decompressDCtx(ctx,out.data(),out.size(),z.data(),z.size());return !ZSTD_isError(n)&&n==out.size();}
static bool bands(ZSTD_DCtx*ctx,const Image&a,const std::vector<Band>&bs,std::span<uint8_t>out,bool skip_last=false){for(size_t i=0;i<bs.size();i++){if(skip_last&&i+1==bs.size())continue;auto&q=bs[i];auto dst=out.subspan(size_t(q.row)*a.bx*16,size_t(q.rows)*a.bx*16);auto n=ZSTD_decompressDCtx(ctx,dst.data(),dst.size(),q.z.data(),q.z.size());if(ZSTD_isError(n)||n!=dst.size())return false;}return true;}
static size_t sum(const std::vector<Band>&b){size_t n=0;for(auto&q:b)n+=q.z.size();return n;}
static std::pair<double,double>stats(std::vector<double>v){std::sort(v.begin(),v.end());return{v[v.size()/2],v[v.size()*95/100]};}
static void fulltest(const char*name,const Image&a,uint32_t px,const std::vector<uint8_t>&z,const std::vector<Band>&bs){std::vector<double>w,b;w.reserve(200);b.reserve(200);std::vector<uint8_t>out(a.raw.size());ZSTD_DCtx*wc=ZSTD_createDCtx(),*bc=ZSTD_createDCtx();if(!wc||!bc)throw std::bad_alloc();for(unsigned i=0;i<220;i++){auto run=[&](bool band){auto t=Clock::now();bool ok=band?bands(bc,a,bs,out):whole(wc,z,out);auto e=Clock::now();if(!ok||out!=a.raw)throw std::runtime_error("full roundtrip mismatch");if(i>=20)(band?b:w).push_back(std::chrono::duration<double,std::micro>(e-t).count());};if(i&1){run(true);run(false);}else{run(false);run(true);}}auto[wp,wp95]=stats(w);auto[bp,bp95]=stats(b);std::printf("full %s band=%upx count=%zu raw=%zu whole_wire=%zu band_payload=%zu band_wire_est=%zu whole_dctx_us=%.1f/%.1f bands_dctx_direct_us=%.1f/%.1f\n",name,px,bs.size(),a.raw.size(),z.size()+24,sum(bs),sum(bs)+bs.size()*8,wp,wp95,bp,bp95);ZSTD_freeDCtx(wc);ZSTD_freeDCtx(bc);}
static void partialtest(const Image&old,const Image&now,uint32_t px,const std::vector<uint8_t>&z,const std::vector<Band>&bs){std::vector<uint8_t>expected=old.raw,out=old.raw;const auto&edge=bs.back();std::copy(now.raw.begin(),now.raw.begin()+size_t(edge.row)*now.bx*16,expected.begin());std::vector<double>w,p;w.reserve(200);p.reserve(200);size_t updated=now.raw.size()-size_t(edge.rows)*now.bx*16;ZSTD_DCtx*wc=ZSTD_createDCtx(),*pc=ZSTD_createDCtx();if(!wc||!pc)throw std::bad_alloc();for(unsigned i=0;i<220;i++){auto runfull=[&]{auto t=Clock::now();bool ok=whole(wc,z,out);auto e=Clock::now();if(!ok||out!=now.raw)throw std::runtime_error("partial whole comparator mismatch");if(i>=20)w.push_back(std::chrono::duration<double,std::micro>(e-t).count());};auto runpartial=[&]{out=old.raw;auto t=Clock::now();bool ok=bands(pc,now,bs,out,true);auto e=Clock::now();if(!ok||out!=expected)throw std::runtime_error("partial edge retention mismatch");if(i>=20)p.push_back(std::chrono::duration<double,std::micro>(e-t).count());};if(i&1){runpartial();runfull();}else{runfull();runpartial();}}auto[wp,wp95]=stats(w);auto[pp,pp95]=stats(p);size_t payload=0;for(size_t i=0;i+1<bs.size();i++)payload+=bs[i].z.size();std::printf("partial %ux%u band=%upx updated=%zu/%zu blocks_raw=%zu ratio=%.2f%% region_payload=%zu estimated_wire=%zu whole_dctx_us=%.1f/%.1f update_dctx_direct_us=%.1f/%.1f\n",now.w,now.h,px,bs.size()-1,bs.size(),updated,100.0*updated/now.raw.size(),payload,payload+(bs.size()-1)*8,wp,wp95,pp,pp95);ZSTD_freeDCtx(wc);ZSTD_freeDCtx(pc);}
int main(int argc,char**argv){try{if(argc!=3)throw std::runtime_error("usage: addbands dark.astc forest.astc");auto d=load(argv[1]),f=load(argv[2]);if(d.w!=f.w||d.h!=f.h)throw std::runtime_error("dimension mismatch");for(uint32_t px:{256u,512u,1024u}){auto db=make_bands(d,px),fb=make_bands(f,px);auto dz=compress(d.raw),fz=compress(f.raw);fulltest("dark",d,px,dz,db);fulltest("forest",f,px,fz,fb);partialtest(d,f,px,fz,fb);}return 0;}catch(const std::exception&e){std::fprintf(stderr,"ERROR: %s\n",e.what());return 2;}}
